def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter, deque
    bg = Counter(x for row in grid for x in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg or (r, c) in seen:
                continue
            color = grid[r][c]
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                a, b = q.popleft()
                cells.append((a, b))
                for da, db in ((1,0),(-1,0),(0,1),(0,-1)):
                    na, nb = a+da, b+db
                    if 0 <= na < h and 0 <= nb < w and (na, nb) not in seen and grid[na][nb] == color:
                        seen.add((na, nb))
                        q.append((na, nb))
            comps.append((color, cells))
    axes = [cells for color, cells in comps if color == 2]
    for color, cells in comps:
        if color == 2:
            continue
        axis = min(axes, key=lambda a: min(abs(r-ar)+abs(c-ac) for r,c in cells for ar,ac in a))
        rows = [r for r,c in axis]
        cols = [c for r,c in axis]
        if len(axis) == 1:
            ar, ac = axis[0]
            reflected = [(2*ar-r, 2*ac-c) for r,c in cells]
        elif len(set(rows)) == 1:
            ar = rows[0]
            reflected = [(2*ar-r, c) for r,c in cells]
        else:
            ac = cols[0]
            reflected = [(r, 2*ac-c) for r,c in cells]
        for r,c in reflected:
            if 0 <= r < h and 0 <= c < w:
                out[r][c] = color
    return out
